<template><view class="page"><MeetingContentHeader title="意见反馈" :activity-id="activityId"/><view class="body"><view class="panel"><view class="label">会议评分</view><view class="rating"><text v-for="n in 5" :key="n" :class="{ active: n <= rating }" @click="rating = n">★</text></view><view class="label">您的建议</view><textarea v-model="content" maxlength="1000" placeholder="欢迎留下您对本次会议的建议"/><button :disabled="submitting" @click="submit">提交反馈</button></view></view></view></template>
<script setup>import { ref } from 'vue';import { onLoad } from '@dcloudio/uni-app';import MeetingContentHeader from '@/components/MeetingContentHeader.vue';import { submitMeetingFeedback } from '@/api/portal/feedback';import { captureMpTokenFromQuery } from '@/utils/mpAuth';const activityId=ref('');const rating=ref(0);const content=ref('');const submitting=ref(false);onLoad(o=>{captureMpTokenFromQuery(o||{});activityId.value=o?.activityId||''});async function submit(){if(!activityId.value){uni.showToast({title:'缺少会议ID',icon:'none'});return}if(!rating.value&&!content.value.trim()){uni.showToast({title:'请填写评分或建议',icon:'none'});return}submitting.value=true;try{await submitMeetingFeedback({activityId:activityId.value,rating:rating.value||null,content:content.value});uni.showToast({title:'反馈已提交'});setTimeout(()=>uni.navigateBack(),700)}finally{submitting.value=false}}</script>
<style lang="scss" scoped>.page{min-height:100vh;background:#f5f7fa}.body{padding:calc(49px + 24rpx) 24rpx}.panel{padding:28rpx;background:#fff;border-radius:12rpx}.label{margin:18rpx 0;color:#303133;font-size:28rpx}.rating text{margin-right:16rpx;color:#dcdfe6;font-size:56rpx}.rating .active{color:#f7ba2a}textarea{box-sizing:border-box;width:100%;height:240rpx;padding:18rpx;background:#f5f7fa;border-radius:8rpx;font-size:28rpx}button{margin-top:28rpx;background:#1f6feb;color:#fff}</style>
